export function Workpane({ className }: WorkpaneProps) {
  const transcript = useSessionStore((state) => state.transcript)
  const setProcessedWordCount = useSessionStore((state) => state.setProcessedWordCount)
  const [revealedCount, setRevealedCount] = useState(0)
  const [pinnedIds, setPinnedIds] = useState<Set<string>>(() => new Set())
  const wordCount = transcript.trim() ? transcript.trim().split(/\s+/).length : 0
  const suggestedCount =
    wordCount < 3 ? 0 : Math.min(STICKERS.length, Math.ceil((wordCount - 2) / 3) * 2)

  useEffect(() => {
    if (suggestedCount <= revealedCount) {
      return
    }
    setRevealedCount(suggestedCount)
    setProcessedWordCount(wordCount)
  }, [revealedCount, setProcessedWordCount, suggestedCount, wordCount])

  const togglePin = (id: string): void => {
    setPinnedIds((current) => {
      const next = new Set(current)
      if (next.has(id)) {
        next.delete(id)
      } else {
        next.add(id)
      }
      return next
    })
  }

  return (
    <section
      aria-label="Evolving visual references"
      className={cn('idea-board min-h-0 overflow-hidden p-3 md:p-6', className)}
    >
      {STICKERS.slice(0, revealedCount).map((sticker, index) => {
        const isPinned = pinnedIds.has(sticker.id)
        return (
          <figure
            className={cn('idea-sticker', `idea-sticker--${index + 1}`, isPinned && 'is-pinned')}
            key={sticker.id}
          >
            <div className="sticker-art">
              <StickerArt variant={sticker.variant} />
            </div>
            <figcaption className="sr-only">{sticker.title}</figcaption>
            <span className="sticker-lane">demo · {sticker.lane}</span>
            <button
              type="button"
              className="pin-button"
              aria-label={`${isPinned ? 'Unpin' : 'Pin'} ${sticker.title}`}
              aria-pressed={isPinned}
              onClick={() => togglePin(sticker.id)}
            >
              <Pin aria-hidden="true" strokeWidth={1.8} />
            </button>
          </figure>
        )
      })}
    </section>
  )
}
import type { ConnectionState, VisualIntent } from '@glia/api-client'
import { create } from 'zustand'

/** Where the browser's microphone permission currently stands. */
export type MicState = 'idle' | 'requesting' | 'granted' | 'denied' | 'unsupported'

export interface TranscriptSegment {
  itemId: string
  text: string
  complete: boolean
}

/**
 * What the screen is showing. Deliberately separate from `MicState`: permission is a device
 * concern, phase is a product one, and a session that has started stays started whether or not
 * the microphone is currently open.
 */
export type SessionPhase = 'hero' | 'session'

interface SessionState {
  micState: MicState
  /** The live capture stream while `micState` is `granted`, and null in every other state. */
  stream: MediaStream | null
  phase: SessionPhase
  /** State and stream move together — a granted state without a stream is not representable. */
  setMic: (micState: MicState, stream: MediaStream | null) => void
  /**
   * Speech has arrived. One-way: stopping the microphone stops listening but must never throw the
   * user back to an empty hero, because by then there is a transcript on screen to destroy.
   */
  startSession: () => void
  connectionState: ConnectionState
  connectionError: string | null
  transcript: string
  transcriptSegments: TranscriptSegment[]
  processedWordCount: number
  intent: VisualIntent | null
  setConnection: (connectionState: ConnectionState, connectionError?: string | null) => void
  setTranscriptState: (transcript: string, transcriptSegments: TranscriptSegment[]) => void
  setProcessedWordCount: (processedWordCount: number) => void
  setIntent: (intent: VisualIntent) => void
  resetRealtime: () => void
}

/**
 * Words on screen mean the session has begun, whichever signal noticed first. The level detector
 * is the fast path — it trips about 250ms into the first sentence, well before any text arrives —
 * but it is not the only one: when the realtime provider is unconfigured the transcript comes from
 * a fixture that nobody had to speak for, and a transcript with no layout to land in is invisible.
 */
function phaseAfter(state: SessionState, transcript: string): SessionPhase {
  return state.phase === 'hero' && transcript.trim() ? 'session' : state.phase
}

export const useSessionStore = create<SessionState>()((set) => ({
  micState: 'idle',
  stream: null,
  phase: 'hero',
  setMic: (micState, stream) => set({ micState, stream }),
  startSession: () => set((state) => (state.phase === 'hero' ? { phase: 'session' } : state)),
  connectionState: 'idle',
  connectionError: null,
  transcript: '',
  transcriptSegments: [],
  processedWordCount: 0,
  intent: null,
  setConnection: (connectionState, connectionError = null) =>
    set({ connectionState, connectionError }),
  setTranscriptState: (transcript, transcriptSegments) =>
    set((state) => ({
      transcript,
      transcriptSegments,
      phase: phaseAfter(state, transcript),
    })),
  setProcessedWordCount: (processedWordCount) =>
    set((state) => ({
      processedWordCount: Math.max(state.processedWordCount, processedWordCount),
    })),
  setIntent: (intent) => set({ intent }),
  resetRealtime: () =>
    set({
      connectionState: 'idle',
      connectionError: null,
      transcript: '',
      transcriptSegments: [],
      processedWordCount: 0,
      intent: null,
    }),
}))

import type { components } from './schema'

export type RealtimeTokenRequest = components['schemas']['RealtimeTokenRequest']
export type RealtimeTokenResponse = components['schemas']['RealtimeTokenResponse']

export {
  parseRealtimeTokenResponse,
  parseServerMessage,
  type ClientMessage,
  type ConnectionState,
  type IntentUpdated,
  type ServerMessage,
  type TranscriptAccepted,
  type VisualIntent,
} from './realtime'
export type ConnectionState = 'idle' | 'connecting' | 'connected' | 'error'

export interface VisualIntent {
  subject: string
  moods: string[]
  styles: string[]
  palette: string[]
  composition: string
  medium: string
  era: string
}

export type IntentSource = 'fixture' | 'local' | 'pioneer'
export type IntentChangeReason = 'initial' | 'subject' | 'medium' | 'era' | 'visual_attributes'

export interface TranscriptAccepted {
  type: 'transcript.accepted'
  item_id: string
  transcript: string
  complete: boolean
}

export interface IntentUpdated {
  type: 'intent.updated'
  revision: number
  transcript: string
  intent: VisualIntent
  stable: boolean
  source: IntentSource
  should_discover: boolean
  change_reasons: IntentChangeReason[]
}

export type ServerMessage =
  | {
      type: 'session.ready'
      session_id: string
      debounce_ms: number
      heartbeat_interval_ms: number
    }
  | TranscriptAccepted
  | IntentUpdated
  | { type: 'pong'; event_id: string }
  | { type: 'error'; code: string; detail: string; recoverable: boolean }

export type ClientMessage =
  | { type: 'transcript.delta'; event_id: string; item_id: string; delta: string }
  | { type: 'transcript.completed'; event_id: string; item_id: string; transcript: string }
  | { type: 'ping'; event_id: string }

type UnknownRecord = Record<string, unknown>

function isRecord(value: unknown): value is UnknownRecord {
  return typeof value === 'object' && value !== null && !Array.isArray(value)
}

function hasString(value: UnknownRecord, key: string): boolean {
  return typeof value[key] === 'string'
}

function hasNumber(value: UnknownRecord, key: string): boolean {
  return typeof value[key] === 'number'
}

function hasBoolean(value: UnknownRecord, key: string): boolean {
  return typeof value[key] === 'boolean'
}

function hasStringArray(value: UnknownRecord, key: string): boolean {
  const candidate = value[key]
  return Array.isArray(candidate) && candidate.every((item) => typeof item === 'string')
}

function parseJson(raw: string): unknown {
  try {
    return JSON.parse(raw) as unknown
  } catch {
    return null
  }
}

export function parseRealtimeTokenResponse(value: unknown): {
  value: string
  expires_at: number
  model: string
} | null {
  if (
    !isRecord(value) ||
    !hasString(value, 'value') ||
    !hasNumber(value, 'expires_at') ||
    !hasString(value, 'model')
  ) {
    return null
  }
  return {
    value: value.value as string,
    expires_at: value.expires_at as number,
    model: value.model as string,
  }
}

function parseVisualIntent(value: unknown): VisualIntent | null {
  if (!isRecord(value) || !hasString(value, 'subject')) {
    return null
  }
  if (
    !hasStringArray(value, 'moods') ||
    !hasStringArray(value, 'styles') ||
    !hasStringArray(value, 'palette') ||
    !hasString(value, 'composition') ||
    !hasString(value, 'medium') ||
    !hasString(value, 'era')
  ) {
    return null
  }
  return {
    subject: value.subject as string,
    moods: value.moods as string[],
    styles: value.styles as string[],
    palette: value.palette as string[],
    composition: value.composition as string,
    medium: value.medium as string,
    era: value.era as string,
  }
}

const intentSources = new Set<IntentSource>(['fixture', 'local', 'pioneer'])
const intentChangeReasons = new Set<IntentChangeReason>([
  'initial',
  'subject',
  'medium',
  'era',
  'visual_attributes',
])

export function parseServerMessage(raw: string): ServerMessage | null {
  const value = parseJson(raw)
  if (!isRecord(value) || !hasString(value, 'type')) {
    return null
  }
  switch (value.type) {
    case 'session.ready':
      if (
        hasString(value, 'session_id') &&
        hasNumber(value, 'debounce_ms') &&
        hasNumber(value, 'heartbeat_interval_ms')
      ) {
        return value as unknown as ServerMessage
      }
      return null
    case 'transcript.accepted':
      if (
        hasString(value, 'item_id') &&
        hasString(value, 'transcript') &&
        hasBoolean(value, 'complete')
      ) {
        return value as unknown as TranscriptAccepted
      }
      return null
    case 'intent.updated': {
      const intent = parseVisualIntent(value.intent)
      if (
        intent &&
        hasNumber(value, 'revision') &&
        hasString(value, 'transcript') &&
        hasBoolean(value, 'stable') &&
        hasString(value, 'source') &&
        intentSources.has(value.source as IntentSource) &&
        hasBoolean(value, 'should_discover') &&
        hasStringArray(value, 'change_reasons') &&
        (value.change_reasons as string[]).every((reason) =>
          intentChangeReasons.has(reason as IntentChangeReason),
        )
      ) {
        return {
          type: 'intent.updated',
          revision: value.revision as number,
          transcript: value.transcript as string,
          intent,
          stable: value.stable as boolean,
          source: value.source as IntentSource,
          should_discover: value.should_discover as boolean,
          change_reasons: value.change_reasons as IntentChangeReason[],
        }
      }
      return null
    }
    case 'pong':
      return hasString(value, 'event_id') ? (value as unknown as ServerMessage) : null
    case 'error':
      if (
        hasString(value, 'code') &&
        hasString(value, 'detail') &&
        hasBoolean(value, 'recoverable')
      ) {
        return value as unknown as ServerMessage
      }
      return null
    default:
      return null
  }
}
{
  "name": "@glia/api-client",
  "version": "0.0.0",
  "private": true,
  "type": "module",
  "types": "./src/index.ts",
  "exports": {
    ".": "./src/index.ts"
  }
}

import {
  type ClientMessage,
  parseRealtimeTokenResponse,
  parseServerMessage,
  type RealtimeTokenRequest,
  type RealtimeTokenResponse,
} from '@glia/api-client'
import { useEffect } from 'react'
import { useSessionStore } from '@/stores/session'

const REQUEST_TIMEOUT_MS = 8_000
const CLIENT_ID_KEY = 'glia:client-id:v1'
const FIXTURE_TRANSCRIPT =
  'A lonely cobalt observatory above the Mediterranean, cinematic, cold, and softly lit.'

type UnknownRecord = Record<string, unknown>

interface TranscriptItem {
  order: number
  text: string
  complete: boolean
}

class RealtimeProviderError extends Error {
  constructor(
    message: string,
    readonly code: string | null,
  ) {
    super(message)
    this.name = 'RealtimeProviderError'
  }
}

function isRecord(value: unknown): value is UnknownRecord {
  return typeof value === 'object' && value !== null && !Array.isArray(value)
}

function clientId(): string {
  try {
    const current = window.localStorage.getItem(CLIENT_ID_KEY)
    if (current) {
      return current
    }
    const created = crypto.randomUUID()
    window.localStorage.setItem(CLIENT_ID_KEY, created)
    return created
  } catch {
    return crypto.randomUUID()
  }
}

function apiUrl(path: string): string {
  const base = import.meta.env.VITE_API_BASE_URL?.replace(/\/$/, '') ?? ''
  return `${base}${path}`
}

function websocketUrl(): string {
  if (import.meta.env.VITE_WS_URL) {
    return import.meta.env.VITE_WS_URL
  }
  const url = new URL('/ws', window.location.href)
  url.protocol = url.protocol === 'https:' ? 'wss:' : 'ws:'
  return url.toString()
}

function requestSignal(parent: AbortSignal): AbortSignal {
  return AbortSignal.any([parent, AbortSignal.timeout(REQUEST_TIMEOUT_MS)])
}

async function fetchToken(signal: AbortSignal) {
  const payload: RealtimeTokenRequest = {
    client_id: clientId(),
    languages: ['en', 'es', 'ca'],
  }
  const response = await fetch(apiUrl('/api/realtime-token'), {
    method: 'POST',
    headers: { 'Content-Type': 'application/json' },
    body: JSON.stringify(payload),
    signal: requestSignal(signal),
  })
  const body: unknown = await response.json()
  if (!response.ok) {
    const detail =
      isRecord(body) && typeof body.detail === 'string'
        ? body.detail
        : 'Unable to start transcription.'
    const code = isRecord(body) && typeof body.code === 'string' ? body.code : null
    throw new RealtimeProviderError(detail, code)
  }
  const token = parseRealtimeTokenResponse(body)
  if (!token) {
    throw new Error('The server returned an invalid transcription credential.')
  }
  return token
}

function delay(milliseconds: number, signal: AbortSignal): Promise<void> {
  return new Promise((resolve) => {
    const timeout = window.setTimeout(resolve, milliseconds)
    signal.addEventListener(
      'abort',
      () => {
        window.clearTimeout(timeout)
        resolve()
      },
      { once: true },
    )
  })
}

async function playFixture(socket: WebSocket, signal: AbortSignal): Promise<void> {
  const itemId = `fixture-${crypto.randomUUID()}`
  const chunks = FIXTURE_TRANSCRIPT.match(/\S+\s*/g) ?? [FIXTURE_TRANSCRIPT]
  for (const chunk of chunks) {
    if (signal.aborted) {
      return
    }
    send(socket, {
      type: 'transcript.delta',
      event_id: crypto.randomUUID(),
      item_id: itemId,
      delta: chunk,
    })
    await delay(110, signal)
  }
  if (!signal.aborted) {
    send(socket, {
      type: 'transcript.completed',
      event_id: crypto.randomUUID(),
      item_id: itemId,
      transcript: FIXTURE_TRANSCRIPT,
    })
  }
}

function openBackendSocket(
  signal: AbortSignal,
  onMessage: (event: MessageEvent<string>) => void,
): Promise<WebSocket> {
  return new Promise((resolve, reject) => {
    const socket = new WebSocket(websocketUrl())
    const fail = () => reject(new Error('Unable to connect to Glia.'))
    socket.addEventListener('message', onMessage)
    socket.addEventListener('open', () => resolve(socket), { once: true })
    socket.addEventListener('error', fail, { once: true })
    signal.addEventListener(
      'abort',
      () => {
        socket.close()
        reject(new DOMException('Connection cancelled', 'AbortError'))
      },
      { once: true },
    )
  })
}

function send(socket: WebSocket, message: ClientMessage): void {
  if (socket.readyState === WebSocket.OPEN) {
    socket.send(JSON.stringify(message))
  }
}

function parseOpenAIEvent(raw: string): UnknownRecord | null {
  try {
    const value: unknown = JSON.parse(raw)
    return isRecord(value) ? value : null
  } catch {
    return null
  }
}

export function useRealtimeTranscription(): void {
  const stream = useSessionStore((state) => state.stream)
  const setConnection = useSessionStore((state) => state.setConnection)
  const setTranscriptState = useSessionStore((state) => state.setTranscriptState)
  const setIntent = useSessionStore((state) => state.setIntent)

  useEffect(() => {
    if (!stream) {
      setConnection('idle')
      return
    }

    const controller = new AbortController()
    const peer = new RTCPeerConnection()
    const events = peer.createDataChannel('oai-events')
    let backend: WebSocket | null = null
    let providerTranscriptionSeen = false
    const existingSegments = useSessionStore.getState().transcriptSegments
    let nextItemOrder = existingSegments.length
    const transcriptItems = new Map<string, TranscriptItem>(
      existingSegments.map((segment, order) => [
        segment.itemId,
        { order, text: segment.text, complete: segment.complete },
      ]),
    )
    const seenProviderEvents = new Set<string>()

    const updateTranscriptItem = (
      itemId: string,
      value: string,
      complete: boolean,
      update: (current: string, incoming: string) => string,
    ): void => {
      const current = transcriptItems.get(itemId)
      if (current?.complete && !complete) {
        return
      }
      transcriptItems.set(itemId, {
        order: current?.order ?? nextItemOrder++,
        text: update(current?.text ?? '', value),
        complete,
      })
      const orderedItems = [...transcriptItems.entries()].sort(
        (left, right) => left[1].order - right[1].order,
      )
      const transcript = orderedItems
        .map(([, item]) => item.text.trim())
        .filter((text) => text.length > 0)
        .join(' ')
      setTranscriptState(
        transcript,
        orderedItems
          .map(([segmentItemId, item]) => ({
            itemId: segmentItemId,
            text: item.text.trim(),
            complete: item.complete,
          }))
          .filter((item) => item.text.length > 0),
      )
    }

    setConnection('connecting')

    const onBackendMessage = (event: MessageEvent<string>): void => {
      if (controller.signal.aborted) {
        return
      }
      const message = parseServerMessage(event.data)
      if (!message) {
        return
      }
      if (message.type === 'transcript.accepted') {
        // Provider events paint locally with zero round-trip latency. Backend echoes can arrive
        // one delta behind, so they are only the source of truth for the deterministic fixture.
        if (providerTranscriptionSeen) {
          return
        }
        updateTranscriptItem(
          message.item_id,
          message.transcript,
          message.complete,
          (_current, transcript) => transcript,
        )
      } else if (message.type === 'intent.updated') {
        setIntent(message.intent)
      } else if (message.type === 'error' && !message.recoverable) {
        setConnection('error', message.detail)
      }
    }

    events.addEventListener('message', (event: MessageEvent<string>) => {
      if (controller.signal.aborted) {
        return
      }
      const message = parseOpenAIEvent(event.data)
      if (!message || typeof message.type !== 'string' || typeof message.item_id !== 'string') {
        return
      }
      const providerEventId =
        typeof message.event_id === 'string' ? message.event_id : crypto.randomUUID()
      if (seenProviderEvents.has(providerEventId)) {
        return
      }
      seenProviderEvents.add(providerEventId)
      if (
        message.type === 'conversation.item.input_audio_transcription.delta' &&
        typeof message.delta === 'string'
      ) {
        providerTranscriptionSeen = true
        updateTranscriptItem(
          message.item_id,
          message.delta,
          false,
          (current, delta) => current + delta,
        )
        if (backend) {
          send(backend, {
            type: 'transcript.delta',
            event_id: providerEventId,
            item_id: message.item_id,
            delta: message.delta,
          })
        }
      } else if (
        message.type === 'conversation.item.input_audio_transcription.completed' &&
        typeof message.transcript === 'string'
      ) {
        providerTranscriptionSeen = true
        updateTranscriptItem(
          message.item_id,
          message.transcript,
          true,
          (_current, transcript) => transcript,
        )
        if (backend) {
          send(backend, {
            type: 'transcript.completed',
            event_id: providerEventId,
            item_id: message.item_id,
            transcript: message.transcript,
          })
        }
      }
    })
    events.addEventListener('open', () => setConnection('connected'))
    events.addEventListener('error', () =>
      setConnection('error', 'The live transcription channel failed.'),
    )
    peer.addEventListener('connectionstatechange', () => {
      if (peer.connectionState === 'failed') {
        setConnection('error', 'The live audio connection failed.')
      }
    })

    for (const track of stream.getAudioTracks()) {
      peer.addTrack(track, stream)
    }

    async function connect(): Promise<void> {
      try {
        backend = await openBackendSocket(controller.signal, onBackendMessage)
        let token: RealtimeTokenResponse
        try {
          token = await fetchToken(controller.signal)
        } catch (error) {
          if (error instanceof RealtimeProviderError && error.code === 'realtime_not_configured') {
            setConnection('connected')
            await playFixture(backend, controller.signal)
            return
          }
          throw error
        }
        const offer = await peer.createOffer()
        await peer.setLocalDescription(offer)
        if (!offer.sdp) {
          throw new Error('The browser could not create an audio offer.')
        }
        const answer = await fetch('https://api.openai.com/v1/realtime/calls', {
          method: 'POST',
          body: offer.sdp,
          headers: {
            Authorization: `Bearer ${token.value}`,
            'Content-Type': 'application/sdp',
          },
          signal: requestSignal(controller.signal),
        })
        if (!answer.ok) {
          throw new Error('OpenAI rejected the live audio connection.')
        }
        await peer.setRemoteDescription({ type: 'answer', sdp: await answer.text() })
      } catch (error) {
        if (!controller.signal.aborted) {
          setConnection(
            'error',
            error instanceof Error ? error.message : 'Unable to start transcription.',
          )
        }
      }
    }

    void connect()

    return () => {
      controller.abort()
      events.close()
      peer.close()
      backend?.close()
    }
  }, [setConnection, setIntent, setTranscriptState, stream])
}
