(async () => {
  const wait = (ms) => new Promise(r => setTimeout(r, ms));
  const runs = [];
  for (const live of [true, false]) {
    window.__session.getState().setMic('idle', null);
    window.__session.getState().resetRealtime();
    await wait(500);
    const ctx = new AudioContext();
    const dest = ctx.createMediaStreamDestination();
    const osc = ctx.createOscillator(); osc.connect(dest); osc.start();
    window.__settings.getState().setLiveDiscovery(live);
    window.__sent = [];
    window.__session.getState().setMic('granted', dest.stream);
    await wait(6000);
    runs.push({ liveDiscovery: live, sentFrames: window.__sent.length, first: window.__sent[0] ?? null, transcript: window.__session.getState().transcript.slice(0, 45) });
  }
  return JSON.stringify(runs, null, 1);
})()

